import{_ as l,l as n,o as t,c as i,v as a,p as d,x as o,d as s,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"每 token 能耗","description":"","frontmatter":{"title":"每 token 能耗","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/energy-per-token.md","filePath":"llm/energy-per-token.md","lastUpdated":1789023840000}'),h={name:"llm/energy-per-token.md"};function E(c,e,k,_,P,A){const r=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="每-token-能耗" tabindex="-1">每 token 能耗 <a class="header-anchor" href="#每-token-能耗" aria-label="Permalink to &quot;每 token 能耗&quot;">​</a></h1><div class="epigraph"><p>搬一次字节的能量和算一次乘加不在一个量级；decode 既然活在带宽屋顶下，每 token 的焦耳就主要由读出权重与 KV 决定。</p><footer>—— Horowitz, Computing&#39;s Energy Problem (and what we can do about it), ISSCC 2014；NLP 训练能耗见 Strubell et al., ACL 2019</footer></div><p><a href="/llm/batch-roofline-knee">上一课</a>用时间谈拐点。本课把同一工作点换成能量：逐步墙钟乘平均功率，再除以本步产出的 token 数（投机可能 \\(\\gt 1\\)）。Horowitz 给出片上算术相对 DRAM 访问的能量差；decode 每步扫 HBM 上的权重，能量画像接近「内存系统」而不是「满负荷 Tensor Core」。后课把焦耳与 GPU 租金收成服务成本；这里先避免用 FLOPs 去估电费。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>时间最优不等于能量最优。过拐点后 TPOT 上升，GPU 仍接近满功率，每 token 焦耳上升；带宽区加大 \\(B\\)，墙钟几乎不变、吞吐上升，每 token 焦耳下降——因为同一份权重搬运摊到更多 token。缺口是：产品若只盯 TPOT，可能把工作点停在 \\(B=1\\) 的「最快单用户」，电费与碳排按最差的每 token 走。Strubell 等人写的是训练；推理的持续功耗在服务上往往是更长的积分。</p><p>投机：一轮若接受 \\(k\\) 个 token，能量是草稿 \\(+\\) 校验，摊到 \\(k\\) 上。接受率低时每 token 焦耳比普通 decode 更差。宣传加速比必须同时报能量，否则是在用热换时。</p><p><span class="marginnote">功率仪表含空闲与散热。应用 \\(P_{\\mathrm{GPU}}\\) 应扣掉空载基线，或明确报「插座」。数据中心 PUE 再乘一截，不在模型内核里，但在后课美元模型里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对稳态 decode：</p> \\[E_{\\mathrm{tok}}\\approx\\frac{\\bar P\\cdot T_{\\mathrm{step}}}{\\mathbb{E}[\\text{本步 token 数}]}. \\]<p>\\(\\bar P\\) 用板载功率或 NVML。\\(B\\) 扫描同时记 \\(E_{\\mathrm{tok}}\\) 与 TPOT：常见形状是 \\(E_{\\mathrm{tok}}\\) 随 \\(B\\) 下降直到拐点，之后回升或变平。量化减字节，带宽区 \\(T_{\\mathrm{step}}\\) 下降，若功率下降不多，\\(E_{\\mathrm{tok}}\\) 仍降。长上下文 \\(\\mathrm{KV}\\) 增大，\\(T_{\\mathrm{step}}\\) 与能量一起涨。</p><p>不要用「总 FLOPs × 某 pJ/FLOP」估 decode： Horowitz 的算术 pJ 会严重低估，因为主项是 DRAM。Prefill 可以更接近算力项，必须分阶段报。</p>',12)),(t(),d(p,null,{default:o(()=>[m(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%B9%B3%E5%9D%87%E5%8A%9F%E7%8E%87%22%5D%20--%3E%20E%5B%22E_tok%20%3D%20P%20%C3%97%20%E6%AD%A5%E6%97%B6%20%2F%20token%20%E6%95%B0%22%5D%0A%20%20T%5B%22%E6%AD%A5%E6%97%B6%22%5D%20--%3E%20E%0A%20%20B%5B%22%E5%8A%A0%E5%A4%A7%20batch%22%5D%20--%3E%20SHARE%5B%22%E6%9D%83%E9%87%8D%E8%83%BD%E9%87%8F%E6%91%8A%E8%96%84%22%5D%0A%20%20SPEC%5B%22%E6%8A%95%E6%9C%BA%E6%8E%A5%E5%8F%97%E7%8E%87%22%5D%20--%3E%20E%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>HBM 访问能量随字节走；Tensor Core 在带宽区经常「闲着也耗静态与时钟」。所以减字节（量化、GQA、MLA）同时降时间和能量；加 FLOPS 卡在带宽区既不降时间也不降能量。碳排还要乘电网因子，Luccioni 等人讨论过推理足迹——本课不把某一克 CO₂ 写成常数，只要求测量链完整：焦耳 → 电网 → PUE。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把训练论文的 MWh 直接除以 token 当推理成本。不要在加速比表格里省略草稿模型的能量。移动端后课再谈；数据中心 GPU 的 \\(E_{\\mathrm{tok}}\\) 不能外推到手机 NPU。后课把 \\(E_{\\mathrm{tok}}\\) 与租时、利用率收成美元。</p><p>出处：Horowitz, ISSCC 2014；Strubell et al., ACL 2019。推理足迹的后续测量以 Luccioni 等公开工作为准，不编造编号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(E_{\\mathrm{tok}}\\) 是功率×步时再摊 token；decode 主项是搬字节。</li><li>带宽区加大 \\(B\\) 通常降每 token 焦耳；过拐点后不一定。</li><li>用 DRAM 能量直觉，不要用 pJ/FLOP 估 decode 电费。</li><li>投机必须按接受率摊；低接受率更耗。</li><li>分阶段报 prefill 与 decode。</li><li>下一课：把时间、能量接到服务成本。</li><li>出处：Horowitz, 2014；Strubell et al., 2019。</li></ul>',7))])}const b=l(h,[["render",E]]);export{T as __pageData,b as default};
